'use strict';
let docs=[], selected=null, busy=false;
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={imported:'To extract',review:'Needs review',approved:'Approved',duplicate:'Duplicate',excluded:'Excluded'};
async function api(path,data){const r=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result;}
function notice(message,error=false){$('notice').className=message?'notice'+(error?' error':''):'';$('notice').textContent=message;}
async function run(message,fn){if(busy){notice('Wait for the current operation to finish.');return;}busy=true;notice(message);document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){notice(e.message,true);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function refresh(){docs=await api('/api/documents');renderList();const counts=[['Documents',docs.length],['Awaiting review',docs.filter(d=>d.status==='review').length],['Approved',docs.filter(d=>d.status==='approved').length],['Exact duplicates',docs.filter(d=>d.status==='duplicate').length]];$('stats').innerHTML=counts.map(([name,n])=>`<div class="stat"><strong>${n}</strong><span>${name}</span></div>`).join('');}
function renderList(){const query=$('search').value.toLowerCase(),filter=$('filter').value;const list=docs.filter(d=>(filter==='all'||filter===d.status)&&(d.name+' '+(d.fields.merchant||'')).toLowerCase().includes(query));$('count').textContent=list.length+' files';$('list').innerHTML=list.length?list.map(d=>`<button class="doc ${selected===d.id?'active':''}" data-id="${d.id}"><span class="doc-title">${esc(d.name)}</span><span class="doc-meta"><span class="badge ${d.status}">${labels[d.status]}</span><span>${esc(d.fields.currency||d.name.split('.').pop().toUpperCase())} ${esc(d.fields.total||'')}</span></span></button>`).join(''):'<div class="empty"><p>No documents here yet.<br>Import your folder or upload a receipt.</p></div>';$('list').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDoc(b.dataset.id));}
async function openDoc(id){try{selected=id;const d=await api('/api/document/'+id);renderList();renderDetail(d);}catch(e){notice(e.message,true);}}
function renderDetail(d){const f=d.fields;const fields=['merchant','receipt_number','date','calendar','currency','total','subtotal','tax','service_charge','document_type'];$('detail').innerHTML=`<div class="detail-head"><div><p class="eyebrow">SOURCE ${d.id.slice(0,8)}</p><h2>${esc(d.name)}</h2></div><span class="badge ${d.status}">${labels[d.status]}</span></div><div class="detail-actions"><button id="read-local">Read text locally</button><a class="button" href="/source/${d.id}" target="_blank" rel="noopener">Open original ↗</a>${d.duplicate_of?`<button id="original">View first copy</button>`:`<button id="extract" class="primary">${d.raw?'Extract again':'Extract fields'}</button>`}${d.name.toLowerCase().endsWith('.pdf')&&!d.name.includes(' · page-')&&!d.duplicate_of?'<button id="split">Split PDF into pages</button>':''}</div>${d.duplicate_of?'<div class="issues">This file matches another file byte for byte. It is excluded from totals to prevent double counting.</div>':`<div class="review-note">Extraction suggests fields; you verify them. Approval makes this document available to questions. Invoices are not automatically treated as paid expenses.</div>${d.issues.length?'<div class="issues">'+d.issues.map(i=>'<p>'+esc(i)+'</p>').join('')+'</div>':''}<form id="review-form"><div class="review-grid">${fields.map(k=>`<div class="field"><label for="f-${k}">${esc(k.replaceAll('_',' '))}${k==='date'?' (YYYY-MM-DD)':''}</label><input id="f-${k}" name="${k}" value="${esc(f[k])}" ${k==='calendar'?'placeholder="gregorian / ethiopian / unknown"':''}><span class="evidence">${f._evidence?.[k]?'Suggested evidence: '+esc(f._evidence[k]):''}</span></div>`).join('')}</div><div class="detail-actions"><button type="button" id="save">Save for review</button><button type="button" id="approve" class="primary">Approve verified fields</button><button type="button" id="exclude" class="warn">Exclude document</button></div></form>`}<details><summary>Original preview</summary>${d.name.toLowerCase().endsWith('.pdf')?`<iframe class="preview" title="Original receipt" src="/source/${d.id}"></iframe>`:`<img class="preview" alt="Original receipt" src="/source/${d.id}" loading="lazy">`}</details><details><summary>Raw extracted text · ${d.raw.length.toLocaleString()} characters</summary><pre>${esc(d.raw||'Extract the document to read its text.')}</pre></details><p class="small">SHA-256: ${d.digest.slice(0,20)}…</p>`;
$('read-local').onclick=()=>run('Reading text locally without a provider request…',async()=>{const r=await api('/api/read-local',{id:d.id});renderDetail(r);notice('Local text reading complete. Fields and approval status are unchanged.');});
if($('split'))$('split').onclick=()=>run('Splitting the bundle locally…',async()=>{const r=await api('/api/split',{id:d.id});await refresh();await openDoc(r.children[0]);notice(r.count+' pages imported. '+r.note);});
if($('original'))$('original').onclick=()=>openDoc(d.duplicate_of);
if($('extract'))$('extract').onclick=()=>run('Reading this document locally, then extracting fields with the configured provider…',async()=>{const r=await api('/api/extract',{id:d.id});await refresh();renderDetail(r);notice('Extraction finished. Compare each field with the original before approving.');});
for(const action of ['save','approve','exclude'])if($(action))$(action).onclick=()=>run('Saving your review…',async()=>{const fields=Object.fromEntries(new FormData($('review-form')));const r=await api('/api/review',{id:d.id,fields,approve:action==='approve',exclude:action==='exclude'});await refresh();renderDetail(r);notice(action==='approve'?'Approved. This document can now support answers.':action==='exclude'?'Excluded from answers.':'Saved for review.');});}
$('import').onclick=()=>run('Importing file names and checking exact duplicates. No provider requests…',async()=>{const r=await api('/api/import',{});await refresh();notice(`Imported ${r.added} new documents. Choose a file to extract.`);});
$('upload-label').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('upload').click();}};
$('upload').onchange=()=>run('Uploading documents to this local workspace…',async()=>{for(const file of $('upload').files){if(file.size>25*1024*1024)throw Error(file.name+' exceeds 25 MB.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('/api/upload',{name:file.name,content});}await refresh();notice('Upload complete. Choose a document to extract.');$('upload').value='';});
$('search').oninput=renderList;$('filter').onchange=renderList;
async function ask(question){const r=await api('/api/ask',{question});$('answer').innerHTML=`<p class="answer-text">${esc(r.answer)}</p><div>${r.sources.map(s=>`<button class="source-link" data-id="${s.id}">${esc(s.name)} · ${esc(s.currency)} ${esc(s.total)}</button>`).join('')}</div><p class="small">${esc(r.note||'')}</p>${r.plan?'<details><summary>How the question was interpreted</summary><pre>'+esc(JSON.stringify(r.plan,null,2))+'</pre></details>':''}`;$('answer').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{openDoc(b.dataset.id);$('detail').scrollIntoView({behavior:'smooth'});});return r;}
$('question-form').onsubmit=e=>{e.preventDefault();run('Finding answers in approved documents…',async()=>{await ask($('question').value);notice('Answer ready. Open a source to check the evidence.');});};
refresh().catch(e=>notice(e.message,true));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_receipt_documents',description:'List imported receipt records and review status without extracting or approving them.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');await refresh();return docs.map(d=>({id:d.id,name:d.name,status:d.status}));}})).catch(()=>{});}catch{}}

$('inspect-table').onclick=()=>run('Checking your CSV locally…',async()=>{
const file=$('table-upload').files[0];if(!file)throw Error('Choose a CSV file first.');
if(file.size>2000000)throw Error('CSV exceeds 2 MB.');
const content=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());
const r=await api('/api/table-inspect',{content});
$('table-report').innerHTML=`<h3>${r.records} records · ${r.columns.length} columns · ${r.total_issues} findings</h3><p>${esc(r.note)}</p><p>${Object.entries(r.counts).map(([k,v])=>esc(k.replaceAll('_',' '))+': '+v).join(' · ')||'No structural issues found. Business rules have not been checked.'}</p><details><summary>Column completeness</summary>${r.columns.map(c=>`<p>Column ${c.position}: ${esc(c.name)||'(blank)'} · ${c.missing} empty cells</p>`).join('')}</details><details open><summary>Findings</summary>${r.issues.map(i=>`<p>Record ${i.record}${i.column?' · column '+i.column:''}: ${esc(i.message)}</p>`).join('')||'<p>No findings.</p>'}</details>`;
notice('CSV check complete. The file has not been changed or saved.');
});

async function refreshDatasets(){const rows=await api('/api/datasets');await refreshCompareLists(rows);$('dataset-list').innerHTML='<option value="">Choose a dataset</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');}
function showDataset(d){
const roles={merchant:'Seller / organization',receipt_number:'Document number',currency:'Currency (ISO code)',total:'Document total (not partial payment)'};
$('dataset-detail').innerHTML=`<h3>${esc(d.name)}</h3><p><a href="/api/dataset-csv/${d.id}" download="dataset.csv">Download spreadsheet-safe CSV</a></p><p>Formula-like cells receive a leading apostrophe in the download. Stored originals are unchanged.</p><p>${d.report.records} records. Original values preserved. Choose columns to compare against approved receipts and invoices.</p><div class="review-grid">${Object.entries(roles).map(([k,label])=>`<div class="field"><label for="map-${k}">${label}</label><select id="map-${k}"><option value="">Choose column</option>${d.report.columns.map((c,i)=>`<option value="${i}" ${d.mapping?.[k]===i?'selected':''}>${c.position}: ${esc(c.name)}</option>`).join('')}</select></div>`).join('')}</div><p>Matching uses seller and document number, then compares currency and total. Amounts must use a dot decimal without thousands separators.</p><button id="confirm-mapping">Confirm mapping</button><button id="compare-dataset">Compare approved documents</button><details><summary>Import and mapping history</summary><pre>${esc(JSON.stringify(d.history,null,2))}</pre></details><div id="comparison"></div>`;
$('confirm-mapping').onclick=()=>run('Saving your column mapping…',async()=>{const mapping={};for(const k of Object.keys(roles)){const v=$('map-'+k).value;if(v==='')throw Error('Choose all four columns.');mapping[k]=Number(v);}showDataset(await api('/api/dataset-map',{id:d.id,mapping}));notice('Mapping confirmed and recorded.');});
$('compare-dataset').onclick=()=>run('Comparing against approved documents…',async()=>{
for(const k of Object.keys(roles))if(!d.mapping||String(d.mapping[k])!==$('map-'+k).value)throw Error('Confirm the current mapping before comparing.');
const r=await api('/api/dataset-reconcile',{id:d.id});
$('comparison').innerHTML=`<h3>Comparison results</h3><p>${Object.entries(r.counts).map(([k,v])=>esc(k)+': '+v).join(' · ')}</p><p>${esc(r.note)}</p><p>Showing first 200 records.</p>${r.results.slice(0,200).map(x=>`<p><strong>Record ${x.record} · ${esc(x.status)}</strong> — ${esc(x.fields.merchant)} / ${esc(x.fields.receipt_number)} · ${esc(x.fields.currency)} ${esc(x.fields.total)} ${x.sources.map(s=>`<a href="/source/${esc(s.id)}" target="_blank" rel="noopener">${esc(s.name)} (${esc(s.currency)} ${esc(s.total)}) ↗</a>`).join(' ')}</p>`).join('')}`;
notice('Comparison complete. No document approvals or source values changed.');});
}
$('save-table').onclick=()=>run('Saving source CSV locally…',async()=>{const f=$('table-upload').files[0];if(!f)throw Error('Choose a CSV first.');if(f.size>2000000)throw Error('CSV exceeds 2 MB.');const content=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());const d=await api('/api/dataset-save',{name:f.name,content});await refreshDatasets();$('dataset-list').value=d.id;showDataset(d);notice('Dataset saved locally. Identical content reuses the existing dataset.');});
$('dataset-list').onchange=()=>run('Opening dataset…',async()=>{if(!$('dataset-list').value){$('dataset-detail').innerHTML='';return;}showDataset(await api('/api/dataset/'+$('dataset-list').value));notice('Dataset opened.');});
refreshDatasets().catch(e=>notice(e.message,true));

let comparisonResult=null,trimSource=null;
async function refreshCompareLists(rows){for(const side of ['left','right']){const el=$('compare-'+side),previous=el.value;el.innerHTML='<option value="">Choose a dataset</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');if(rows.some(r=>r.id===previous))el.value=previous;}}
async function columns(side){const id=$('compare-'+side).value;$('apply-trim').hidden=true;trimSource=null;comparisonResult=null;$('table-comparison').textContent='Choose columns and compare.';$('export-comparison').hidden=true;if(!id){$(side+'-columns').innerHTML='';return;}const d=await api('/api/dataset/'+id);$(side+'-columns').innerHTML=['key','value'].map(role=>`<label for="${side}-${role}">${role==='key'?'Unique key':'Value to compare'}</label><select id="${side}-${role}"><option value="">Choose column</option>${d.report.columns.map((c,i)=>`<option value="${i}">${esc(c.name)}</option>`).join('')}</select>`).join('');}
for(const side of ['left','right'])$('compare-'+side).onchange=()=>run('Loading columns…',async()=>{await columns(side);notice('Choose a key and a value column.');});
$('demo').onclick=()=>run('Loading synthetic inventory examples…',async()=>{const d=await api('/api/demo',{});await refreshDatasets();for(const side of ['left','right']){$('compare-'+side).value=d[side];await columns(side);$(side+'-key').value='0';$(side+'-value').value='1';}notice('Demo ready: compare to find quantity conflicts, duplicate keys, and one-sided records. Preview left-side cleanup to resolve the spaced product code.');});
function renderComparison(){if(!comparisonResult)return;const r=comparisonResult,filter=$('issue-filter').value,rows=r.results.filter(x=>filter==='all'||x.status===filter);$('table-comparison').innerHTML=`<div class="stats">${Object.entries(r.counts).map(([k,v])=>`<div class="stat"><strong>${v}</strong><span>${esc(k.replaceAll('_',' '))}</span></div>`).join('')}</div><p>${esc(r.note)}</p><p>Showing ${Math.min(rows.length,200)} of ${rows.length} filtered groups. Full report contains every group.</p><div class="table-scroll"><table class="result-table"><thead><tr><th>Key</th><th>Status</th><th>Left values / source records</th><th>Right values / source records</th></tr></thead><tbody>${rows.slice(0,200).map(x=>`<tr><td>${esc(x.key)||'(empty)'}</td><td class="status-${x.status}">${esc(x.status.replaceAll('_',' '))}</td><td>${x.left.map(v=>esc(v.value)+' · record '+v.record).join('<br>')||'—'}</td><td>${x.right.map(v=>esc(v.value)+' · record '+v.record).join('<br>')||'—'}</td></tr>`).join('')}</tbody></table></div>`;}
$('compare-tables').onclick=()=>run('Comparing uploaded records…',async()=>{const payload={};for(const side of ['left','right']){payload[side]=$('compare-'+side).value;if(!payload[side])throw Error('Choose both datasets.');for(const role of ['key','value']){const el=$(side+'-'+role);if(!el||el.value==='')throw Error('Choose all key and value columns.');payload[side+'_'+role]=Number(el.value);}}comparisonResult=await api('/api/compare',payload);comparisonResult.mapping=payload;renderComparison();$('export-comparison').hidden=false;notice('Comparison complete. Original records are unchanged.');});
$('issue-filter').onchange=renderComparison;
$('preview-trim').onclick=()=>run('Preparing a cleanup preview…',async()=>{const id=$('compare-left').value;if(!id)throw Error('Choose a left dataset first.');const r=await api('/api/trim',{id});trimSource=id;$('cleaning-preview').innerHTML=`<h3>${r.count} cells would change</h3><p>Only leading/trailing whitespace is removed. Duplicates and blank values are retained. Original dataset stays unchanged. Showing first 100 changes.</p><pre>${esc(JSON.stringify(r.changes.slice(0,100),null,2))}</pre>`;$('apply-trim').hidden=!r.count;notice('Review the changes before applying.');});
$('apply-trim').onclick=()=>run('Creating a cleaned version…',async()=>{if(!trimSource||trimSource!==$('compare-left').value)throw Error('Preview the selected dataset first.');const r=await api('/api/trim',{id:trimSource,apply:true});await refreshDatasets();if(r.derived){$('compare-left').value=r.derived;await columns('left');}notice('Cleaned version saved with a link to its source in history. Choose columns and compare again.');});
$('export-comparison').onclick=()=>{if(!comparisonResult)return;const url=URL.createObjectURL(new Blob([JSON.stringify(comparisonResult,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='comparison-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

api('/api/capabilities').then(c=>{$('provider-status').textContent=c.provider_configured?(c.ocr_ready?'Extraction is configured. Model: '+c.model+'.':'Provider configured. PDF text reader: '+(c.reader.pdf_text_ready?'ready':'not installed')+'. Image OCR: not ready. See optional reader setup in README.'):'Extraction needs provider configuration. CSV comparison and manual document review work without credentials.';}).catch(()=>{$('provider-status').textContent='Setup status unavailable. See README for document extraction requirements.';});
